args.content:
.page {
  box-sizing: border-box;
  min-height: 100vh;
  max-width: 960px;
  margin: 0 auto;
  padding: 64px 24px;
  display: flex;
  flex-direction: column;
  gap: 72px;
  color: var(--g-color-text-primary);
  font-family: inherit;
}

.hero {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.hero__title {
  margin: 0;
  font-size: clamp(32px, 5vw, 48px);
  line-height: 1.15;
  font-weight: 700;
}

.hero__subtitle {
  margin: 0;
  max-width: 600px;
  font-size: 18px;
  line-height: 1.5;
  color: var(--g-color-text-secondary);
}

.advantages__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.advantage {
  padding: 24px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: 12px;
  background: var(--g-color-base-background);
}

.advantage__title {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 600;
}

.advantage__text {
  margin: 0;
  font-size: 15px;
  line-height: 1.5;
  color: var(--g-color-text-secondary);
}

.cta {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.cta__title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
}

.cta__text {
  margin: 0 0 8px;
  font-size: 16px;
  color: var(--g-color-text-secondary);
}

@media (max-width: 720px) {
  .page {
    padding: 40px 16px;
    gap: 48px;
  }

  .advantages__list {
    grid-template-columns: 1fr;
  }
}

